from itertools import tee, islice

def unique_justseen(iterable, key=None):
    """Yields elements in order, ignoring serial duplicates

    >>> list(unique_justseen('AAAABBBCCDAABBB'))
    ['A', 'B', 'C', 'D', 'A', 'B']
    >>> list(unique_justseen('ABBCcAD', str.lower))
    ['A', 'B', 'C', 'A', 'D']

    """
    def dupes(iterable):
        a, b = tee(iterable)
        return (x for x, y in zip(a, islice(b, 1, None)) if x != y)

    if key is None:
        return [next(iterable)] + [x for x in dupes(iterable) if x != key(x)]
    else:
        return [next(iterable, key=key)] + [x for x in dupes(iterable) if key(x) != key(x)]

